import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

public class LineMatcher {

    private static final String STOP = "END";

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            System.out.println("Enter text (type " + STOP + " on a line by itself to finish):");
            List<String> lines = readLines(reader);
            if (lines.isEmpty()) {
                System.out.println("No text entered. Nothing to match.");
                return;
            }

            System.out.println("Enter regex:");
            String patternInput = reader.readLine();
            if (patternInput == null) {
                System.out.println("No pattern entered.");
                return;
            }

            int flagPosition = patternInput.indexOf('/');
            if (flagPosition != -1) {
                patternInput = patternInput.substring(0, flagPosition);
            }
            if (patternInput.trim().isEmpty()) {
                System.out.println("Empty pattern. Nothing to match.");
                return;
            }

            Pattern pattern;
            try {
                pattern = Pattern.compile(patternInput);
            } catch (PatternSyntaxException e) {
                System.out.println("Invalid regex: " + e.getMessage());
                return;
            }

            int count = 0;
            for (String line : lines) {
                if (pattern.matcher(line).find()) {
                    count++;
                }
            }

            System.out.println();
            System.out.println("Matches: " + count);

        } catch (IOException e) {
            System.err.println("Read error: " + e.getMessage());
        }
    }

    private static List<String> readLines(BufferedReader reader) throws IOException {
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            if (STOP.equals(line.trim())) {
                break;
            }
            lines.add(line);
        }
        return lines;
    }
}
