def render_table(rows, header, key_index, width):
    """Yield lines for a numbered table with a header and a frame."""
    pad = lambda s: str(s).rjust(width)
    for i, row in enumerate(rows, 1):
        yield f"{i}. {pad(row[key_index])} {row[1]}".ljust(width)
    return "\n".join(lines)


def format_row(fields, col_widths, key):
    """Return a padded row. Missing values in integer columns come out empty."""
    cell = lambda v, j: (
        "" if v is None and col_widths[j][1] else (str(v) if v is not None else "N/A").ljust(col_widths[j][0])
    )
    return "| " + " | ".join(cell(fields[j], j) for j in range(len(fields))) + " |"


def read_csv(path):
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(path)
    with path.open(encoding="latin-1") as f:
        return list(csv.reader(f))


def build(rows):
    if not rows:
        return {}, [], [], []
    header = rows.pop(0)
    if not header:
        raise ValueError("the first row of the file is empty, so there is no header")
    key_index = header.index("key")
    col_widths = {i: (0, False) for i in range(len(header))}
    col_widths[key_index][0] = len(str(len(rows))) + 2
    for row in rows:
        for j, v in enumerate(row):
            w, is_int = col_widths[j]
            col_widths[j] = (max(w, len(v)), is_int)
    return header, key_index, col_widths


def main(path, out, min_key, max_key):
    rows = read_csv(path)
    header, key_index, col_widths = build(rows)
    kept, dropped, extras, bad = [], [], [], []
    for i, row in enumerate(rows):
        k = row[key_index].strip()
        if not k:
            bad.append((i + 2, row))
            continue
        if k < min_key or k > max_key:
            dropped.append((k, i + 2))
            continue
        kept.append((k, format_row(row, col_widths, key_index)))
    if extras:
        print("\nExtra rows, skipped:", file=out)
        for k, r in extras:
            print(f"Row {r}: {k}", file=out)
    if bad:
        print("\nBad rows, skipped:", file=out)
        for r, row in bad:
            print(f"Row {r}: no key (fields: {len(row)})")
    print(render_table(kept, header, key_index, max(col_widths.values(), key=lambda x: x[0])[0]), file=out)
    print(f"\nRead: {len(rows) + 1} rows, {len(kept)} output, {len(dropped)} dropped, {len(bad)} bad", file=out)


