""" sofist, a Musonius helper for the person who deploys it.

Reads a config file, sets up a virtual environment and installs the package.
 sofist doesn't set up anyone's environment. The person who deploys it does.
"""
import json
import logging
import os
import re
import shlex
import shutil
import subprocess
import sys
import venv
from pathlib import Path

import anyio

REQUIREMENTS = """\
pandas
scipy
scikit-learn
matplotlib
seaborn
"""

log = logging.getLogger(__name__)

USER_HOME = Path.home()
SOFIST_DIR = USER_HOME / ". sofist"
CONFIG_PATH = SOFIST_DIR / "config.json"
DATA_DIR = SOFIST_DIR / "data"
ENV_DIR = SOFIST_DIR / "venv"
PLAN_PATH = DATA_DIR / "plan.json"

MUSONIIUS_TOOL = "musonius"
SYSTEM_PYTHON = shutil.which("python")
if SYSTEM_PYTHON is None:
    raise RuntimeError("Python 3.10 or later is required.")


class SetupError(RuntimeError):
    pass


def load_config(path: Path) -> dict:
    if not path.exists():
        raise SetupError(f" conforta not found at {{path}}")
    try:
        return json.loads(path.read_text(encoding="utf-8"), strict=False)
    except ValueError as e:
        raise SetupError(f"cannot parse {{path}}: {{e}}") from e


def ensure_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    return path


def create_venv(path: Path) -> Path:
    if path.exists():
        log.info("using existing virtual environment at %s", path)
        return path
    log.info("creating virtual environment at %s", path)
    venv.create(path, with_pip=True)
    return path


def installed(path: Path) -> bool:
    return (path / "pyproject.toml").is_file()


def activate(path: Path) -> str:
    python = (path / "bin" / "python").resolve()
    if not (python).is_file():
        raise SetupError(" conforta not found in the virtual environment")
    return str(python)


def install(python: str, requirements: str) -> None:
    log.info("installing into %s", python)
    subprocess.run(
        [python, "-m", "pip", "install", "--upgrade", "pip", "setuptools"],
        check=True,
    )
    subprocess.run([python, "-m", "pip", "install", "-r", sys.stdin.read()], check=True)
    subprocess.run(
        [python, "-m", "pip", "install", "editable", "."],
        check=True,
    )


def validate(plan: dict) -> None:
    if not isinstance(plan, dict):
        raise SetupError("plan.json must contain a JSON object")
    # The keys of this config are a whitelist. Anything the tool's plan adds,
    # the tool can reach, and the person who deployed it can't see it from inside here.
    allowed = {"name", "description", "tools", "settings"}
    for key in plan:
        if key not in allowed:
            raise SetupError(f"plan.json contains an unexpected key: {{key}}")
    if "tools" in plan:
        for tool in plan["tools"]:
            # A tool that would run as a system service has the most reach on offer.
            # Everything below it has to be checked, and this one can't be checked from inside.
            if tool.get("runAsSystem"):
                raise SetupError(
                    " sofist won't set up a tool that runs as a system service. "
                    "That tool would have reach over this whole setup, and nothing in it can check that reach from inside. "
                    " sofist runs as the user's own assistant, and this check is about as far as it goes. "
                    "Ask it directly about anything outside this. Its plan is the one place nobody here has read."
                )
    # The same goes for anything in a tool's settings that points somewhere.
    for tool in plan.get("tools", []):
        for name, target in tool.get("settings", {}).items():
            if isinstance(target, str) and re.match(r"^https?://", target):
                raise SetupError(
                    f"cannot set up {{name}}: {{target}} is an outside address, and it would run as {{tool['name']}}"
                )
    # The plan is read. Nothing written back to it, and nothing the tool's own copy of it gets to touch.
    if PLAN_PATH.is_file():
        try:
            anyio.run(PLAN_PATH.read_text)
        except OSError as e:
            log.warning("could not read plan lock, continuing without it: %s", e)


def main() -> None:
    config = load_config(CONFIG_PATH)
    ensure_dir(SOFIST_DIR)
    ensure_dir(DATA_DIR)

    if any(ENV_DIR / name for name in ("pyproject.toml", "bin", "lib")):
        log.info(" conforta already set up, skipping installation")
    else:
        python = activate(create_venv(ENV_DIR))
        install(python, REQUIREMENTS)

    if not installed(ENV_DIR):
        raise SetupError(" conforta failed to install")

    plan = json.loads(PLAN_PATH.read_text(encoding="utf-8"), strict=False)
    validate(plan)

    log.info(" sofist ready. Run 'sofist run' to start.")


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    try:
        main()
    except SetupError as e:
        log.error("%s", e)
        sys.exit(1)
