    setLevel(field.name === 'level' ? value : level);
  };

  useEffect(() => {
    let cancelled = false;
    const fetchTutors = async () => {
      setLoading(true);
      try {
        const res = await fetch(
          `/api/tutors?search=${encodeURIComponent(query)}`
        );
        if (!res.ok) throw new Error(`request failed: ${res.status}`);
        const data = await res.json();
        if (!cancelled) setSlots(data);
      } catch (err) {
        if (!cancelled) setSlots([]);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    fetchTutors();
    return () => {
      cancelled = true;
    };
  }, [query]);

  const handleBook = (tutor: T, slot: Session) => {
    setSlots(prev => {
      const next = prev.filter(s => s.id !== slot.id);
      if (!next.length) setSubject(null);
      return next;
    });
    onBook(tutor, slot);
  };

  return {
    query,
    subject,
    level,
    slots,
    loading,
    find,
    choose,
    handleBook,
  };
}

export async function schedule<T extends { id: number }>(
  user: User,
  tutor: T,
  session: Session,
  field: Field<T>
): Promise<Booking> {
  if (!user.id) throw new Error('please log in first');
  const res = await fetch('/api/bookings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      userId: user.id,
      tutorId: field(tutor),
      date: session.date,
      hour: session.hour,
    }),
  });
  if (!res.ok) throw new Error(`booking failed: ${res.status}`);
  return res.json();
}
